import {readTravel,validateTravelEdits} from './travel-editor.js';
import {readRegionMap,REGION_PAGES} from './region-map.js';
export function travelWorkshop(api){const $=s=>document.querySelector(s),esc=api.esc;let native,hash,draft,reader,region;
 const save=()=>{validateTravelEdits({[hash]:draft});api.change(()=>{api.project().travelEdits??={};if(draft.rules||draft.spawn||Object.keys(draft.fly).length||Object.keys(draft.grids).length)api.project().travelEdits[hash]=structuredClone(draft);else delete api.project().travelEdits[hash];});api.toast?.('Travel settings saved. Export the edited ROM to use them.');};
 function open(){const session=api.session();if(!session)throw Error('Open the original ROM first.');hash=session.id;reader=session.reader;native=readTravel(reader,hash);region=readRegionMap(reader,hash);draft=structuredClone(api.project().travelEdits?.[hash]||{fly:{},grids:{}});show();}
 function show(){api.modal('Spawn, Fly & cursor',`<p>Change the new-game starting tile, existing Fly landing tiles and Town Map cursor selection. Story scripts can still warp the player after the initial spawn. Existing saves keep their current position.</p><button id="travelSpawn" type="button" class="studio-record">New-game starting map · ${esc(draft.spawn?.mapKey||native.spawn.mapKey)}</button><details open><summary>Fly landing tiles</summary><p class="hint-line">Coordinates change the landing in its existing map. Native visit flags and whiteout respawn centres remain tied to that destination.</p>${native.fly.map(f=>`<button data-travel-fly="${f.id}" type="button" class="studio-record">${esc(f.name)} · ${(draft.fly[f.id]||f).x},${(draft.fly[f.id]||f).y}</button>`).join('')}</details><button id="travelCursor" type="button" class="studio-record">Edit Town Map cursor selection</button>`,save,'Save travel settings');$('#travelSpawn').onclick=spawn;$('#travelCursor').onclick=()=>cursor();document.querySelectorAll('[data-travel-fly]').forEach(b=>b.onclick=()=>fly(+b.dataset.travelFly));}
 function coords(s){return `<label>X<input id="travelX" type="number" min="0" max="255" value="${s.x}"></label><label>Y<input id="travelY" type="number" min="0" max="255" value="${s.y}"></label>`;}
 function spawn(){const s=draft.spawn||native.spawn,generated=api.project().maps.filter(m=>m.rom?.generated&&!m.rom?.isCopy),selection=s.mapId?'project:'+s.mapId:s.mapKey;api.modal('New-game spawn',`<label>Map<select id="travelSpawnMap">${reader.maps.map(m=>`<option value="${esc(m.key)}" ${m.key===selection?'selected':''}>${esc(m.label||m.key)} · ${esc(m.key)}</option>`).join('')}${generated.map(m=>`<option value="project:${esc(m.id)}" ${selection==='project:'+m.id?'selected':''}>${esc(m.name)} · new map</option>`).join('')}</select></label>${coords(s)}<p class="hint-line">Choose a clear tile. Fresh games run the destination’s normal entry scripts.</p><button id="travelReset" type="button">Restore original spawn</button>`,()=>{const choice=$('#travelSpawnMap').value,next={x:+$('#travelX').value,y:+$('#travelY').value,...(choice.startsWith('project:')?{mapId:choice.slice(8)}:{mapKey:choice})};validateTravelEdits({[hash]:{...draft,spawn:next}});draft.spawn=next;show();},'Keep spawn');$('#travelReset').onclick=()=>{delete draft.spawn;show();};}
 function fly(id){const s=draft.fly[id]||native.fly[id];api.modal('Fly · '+native.fly[id].name,`<p>Map ${esc(native.fly[id].mapKey)}. Land on a walkable tile away from doors, water and obstacles.</p>${coords(s)}<button id="travelReset" type="button">Restore original landing</button>`,()=>{const next={x:+$('#travelX').value,y:+$('#travelY').value};validateTravelEdits({[hash]:{...draft,fly:{...draft.fly,[id]:next}}});draft.fly[id]=next;show();},'Keep landing');$('#travelReset').onclick=()=>{delete draft.fly[id];show();};}
 function cursor(page=0,layer=0,brush=88){api.modal('Town Map cursor selection',`<p>Each coloured cell selects a location when the native cursor crosses it. This grid controls selection independently of the artwork and player marker.</p><label>Region<select id="travelCursorPage">${REGION_PAGES.map((n,i)=>`<option value="${i}" ${i===page?'selected':''}>${n}</option>`).join('')}</select></label><label>Layer<select id="travelCursorLayer"><option value="0" ${layer===0?'selected':''}>Towns & routes</option><option value="1" ${layer===1?'selected':''}>Dungeons</option></select></label><label>Location brush<select id="travelCursorBrush">${region.locations.map((l,i)=>`<option value="${i+88}" ${brush===i+88?'selected':''}>${esc(l.name)}</option>`).join('')}<option value="197" ${brush===197?'selected':''}>No location</option></select></label><canvas id="travelCursorCanvas" width="22" height="15" aria-label="Paint cursor locations" style="width:100%;max-width:660px;image-rendering:pixelated;touch-action:none;border:2px solid #687550"></canvas><p id="travelCursorStatus" role="status">Tap or drag to paint the selected location.</p><button id="travelCursorReset" type="button">Restore this region’s cursor grid</button>`,show,'Keep cursor changes');const canvas=$('#travelCursorCanvas'),ctx=canvas.getContext('2d');const draw=()=>{const im=ctx.createImageData(22,15),grid=draft.grids[page]||native.grids[page];for(let i=0;i<330;i++){const id=grid[layer*330+i],h=(id*137)%360,c=id===197?[20,28,20]:[70+(id*53)%170,70+(id*97)%170,70+(id*37)%170];im.data.set([...c,255],i*4);}ctx.putImageData(im,0,0);};draw();let down=false;const paint=e=>{const r=canvas.getBoundingClientRect(),x=Math.floor((e.clientX-r.left)*22/r.width),y=Math.floor((e.clientY-r.top)*15/r.height);if(x<0||x>=22||y<0||y>=15)return;draft.grids[page]??=[...native.grids[page]];draft.grids[page][layer*330+y*22+x]=+$('#travelCursorBrush').value;$('#travelCursorStatus').textContent=x+','+y+' · '+$('#travelCursorBrush').selectedOptions[0].textContent;draw();};canvas.onpointerdown=e=>{e.preventDefault();down=true;canvas.setPointerCapture?.(e.pointerId);paint(e);};canvas.onpointermove=e=>{if(down)paint(e);};canvas.onpointerup=canvas.onpointercancel=()=>down=false;$('#travelCursorPage').onchange=()=>cursor(+$('#travelCursorPage').value,layer,+$('#travelCursorBrush').value);$('#travelCursorLayer').onchange=()=>cursor(page,+$('#travelCursorLayer').value,+$('#travelCursorBrush').value);$('#travelCursorReset').onclick=()=>{delete draft.grids[page];draw();};}
 return{open};}
